const SVG_NAMESPACE = "http://www.w3.org/2000/svg";
const CANVAS_ATTRIBUTE = "data-metallicss-canvas";
const SELECTOR = ".metallicss";
const renderStates = new WeakMap();
const controllers = new WeakMap();

export const presets = Object.freeze({
  silver: "#f4f7fa",
  steel: "#d9e0e7",
  chrome: "#ffffff",
  gold: "#f5c451",
  copper: "#cf7546",
  lead: "#77818d",
  titanium: "#a7a9b4",
  gunmetal: "#53606d",
});

function createTag(document, name, { inner, props }) {
  const elem = document.createElementNS(SVG_NAMESPACE, name);

  props && Object.entries(props).forEach((prop) => elem.setAttribute(...prop));
  inner?.forEach((innerElem) => elem.append(innerElem));

  return elem;
}

function clamp(value, minimum, maximum) {
  return Math.min(Math.max(value, minimum), maximum);
}

function number(value, fallback, minimum, maximum) {
  const parsed = Number.parseFloat(value);

  return clamp(Number.isFinite(parsed) ? parsed : fallback, minimum, maximum);
}

function supportedColor(view, value) {
  const candidate = String(value).trim();
  if (!candidate) return false;
  if (view.CSS?.supports) return view.CSS.supports("color", candidate);

  const probe = view.document.createElement("span");
  probe.style.color = candidate;
  return Boolean(probe.style.color);
}

function angleInDegrees(value, fallback = 90) {
  let candidate = String(value).trim().toLowerCase();
  if (!candidate) return fallback;

  let multiplier = 1;
  for (const [suffix, factor] of [
    ["turn", 360],
    ["grad", 0.9],
    ["rad", 180 / Math.PI],
    ["deg", 1],
  ]) {
    if (!candidate.endsWith(suffix)) continue;
    candidate = candidate.slice(0, -suffix.length).trim();
    multiplier = factor;
    break;
  }

  const parsed = Number(candidate);
  return clamp(Number.isFinite(parsed) ? parsed * multiplier : fallback, -3600, 3600);
}

function radiusInPixels(value, size) {
  const parsed = Number.parseFloat(value);

  if (!Number.isFinite(parsed)) return 0;
  return value.includes("%") ? (parsed / 100) * size : parsed;
}

function largestRadius(styles, width, height) {
  return Math.max(
    ...[
      styles.borderTopLeftRadius,
      styles.borderTopRightRadius,
      styles.borderBottomRightRadius,
      styles.borderBottomLeftRadius,
    ].flatMap((corner) => {
      const [horizontal = "0", vertical = horizontal] = corner.split(/\s+/);
      return [radiusInPixels(horizontal, width), radiusInPixels(vertical, height)];
    }),
  );
}

function directCanvas(element) {
  if (!element?.children) return null;

  return (
    Array.from(element.children).find(
      (child) => child.tagName === "CANVAS" && child.hasAttribute(CANVAS_ATTRIBUTE),
    ) || null
  );
}

function dispatch(element, name, detail) {
  const Event = element.ownerDocument?.defaultView?.CustomEvent;

  if (Event) element.dispatchEvent(new Event(name, { detail }));
}

const xmlns = SVG_NAMESPACE,
  dims = { height: 2048, width: 2048 },
  sRGB = { ["color-interpolation-filters"]: "sRGB" },
  createMap = (document) =>
    createTag(document, "feImage", {
      props: {
        ...dims,
        ...sRGB,
        href: "data:image/png;base64,",
        preserveAspectRatio: "none",
        result: "map",
      },
    });
export const metallicss = (elem, { force = false } = {}) => {
  if (!elem || elem.nodeType !== 1) {
    throw new TypeError("metallicss() expects an Element");
  }

  const view = elem.ownerDocument?.defaultView;
  const { offsetHeight: y, offsetWidth: x } = elem;

  if (!view || x <= 0 || y <= 0) return null;

  const tag = (name, options) => createTag(elem.ownerDocument, name, options);
  const styles = view.getComputedStyle(elem);
  const rawDepth = number(styles.getPropertyValue("--convexity"), 4, -24, 24);
  const absRawDepth = Math.abs(rawDepth);
  const radius = largestRadius(styles, x, y);
  const inverse = rawDepth < 0;
  const canvas = directCanvas(elem) || elem.ownerDocument.createElement("canvas");
  const context = canvas.getContext("2d", { alpha: false });

  if (!context) {
    dispatch(elem, "metallicss:error", {
      error: new Error("Canvas 2D is not available"),
    });
    return null;
  }

  const finishValue = styles.getPropertyValue("--metal").trim();
  const finish = finishValue.toLowerCase();
  const customColor = styles.getPropertyValue("--metallicss-color").trim();
  const finishColor =
    finish === "neutral"
      ? styles.backgroundColor
      : presets[finish] || finishValue || presets.silver;
  const fill = supportedColor(view, customColor)
    ? customColor
    : supportedColor(view, finishColor)
      ? finishColor
      : presets.silver;
  const intensity = number(styles.getPropertyValue("--metallicss-intensity"), 1, 0, 2);
  const angle = angleInDegrees(styles.getPropertyValue("--metallicss-angle"), 90);
  const resolutionValue = styles.getPropertyValue("--metallicss-resolution").trim();
  const resolution = resolutionValue
    ? number(resolutionValue, 1, 0.25, 3)
    : Math.min(view.devicePixelRatio || 1, 2);
  const canvasWidth = Math.min(2048, Math.max(1, Math.round(x * resolution)));
  const canvasHeight = Math.min(2048, Math.max(1, Math.round(y * resolution)));
  const signature = [
    x,
    y,
    rawDepth,
    radius,
    fill,
    intensity,
    angle,
    canvasWidth,
    canvasHeight,
  ].join("|");
  const renderState = renderStates.get(elem) || {
    generation: 0,
    ready: false,
    pending: false,
    signature: "",
    url: null,
  };

  renderStates.set(elem, renderState);

  if (!force && renderState.signature === signature && (renderState.ready || renderState.pending)) {
    return canvas;
  }

  if (renderState.url) {
    if (renderState.image) {
      renderState.image.onload = null;
      renderState.image.onerror = null;
      renderState.image = null;
    }
    view.URL.revokeObjectURL(renderState.url);
    renderState.url = null;
  }

  renderState.generation += 1;
  renderState.pending = true;
  renderState.ready = false;
  renderState.signature = signature;
  elem.removeAttribute("data-metallicss-ready");

  const generation = renderState.generation;
  const serializer = new view.XMLSerializer();
  const domUrl = view.URL || view.webkitURL;
  const inner = [
    tag("image", {
      props: {
        href: "data:image/png;base64,",
        ...dims,
        preserveAspectRatio: "none",
      },
    }),
    tag("rect", {
      props: {
        ...dims,
        fill,
        style: "mix-blend-mode: luminosity",
        opacity: intensity / 4,
      },
    }),
    tag("rect", {
      props: {
        x: 512,
        y: 512,
        width: 1024,
        height: 1024,
        fill: "url(#color)",
        style: "mix-blend-mode: color",
      },
    }),
    tag("rect", {
      props: {
        ...dims,
        fill,
        opacity: intensity / 4,
        style: "mix-blend-mode: overlay",
      },
    }),
  ];
  let url;
  const rx = clamp(
    Math.trunc((y / 2 < radius ? 1024 * (y / x) : radius * (2048 / x)) / 4) - absRawDepth * 4,
    0,
    1024,
  );
  const ry = clamp(
    Math.trunc((x / 2 < radius ? 1024 * (x / y) : radius * (2048 / y)) / 4) - absRawDepth * 4,
    0,
    1024,
  );
  const lensHeight = clamp(25 - (absRawDepth / 3) * ((x + y) / 2 / y), 1, 100);
  const lensWidth = clamp(25 - (absRawDepth / 3) * ((x + y) / 2 / x), 1, 100);
  const startedAt = view.performance?.now() ?? Date.now();
  const tempImage = new view.Image();

  if (!canvas.hasAttribute(CANVAS_ATTRIBUTE)) {
    canvas.classList.add("metal");
    canvas.setAttribute(CANVAS_ATTRIBUTE, "");
    canvas.setAttribute("aria-hidden", "true");
    elem.append(canvas);
  }

  if (!renderState.originalStyles) {
    renderState.originalStyles = {};
    if (styles.position === "static") {
      renderState.originalStyles.position = [
        elem.style.getPropertyValue("position"),
        elem.style.getPropertyPriority("position"),
      ];
      elem.style.setProperty("position", "relative");
    }
    if (styles.isolation !== "isolate") {
      renderState.originalStyles.isolation = [
        elem.style.getPropertyValue("isolation"),
        elem.style.getPropertyPriority("isolation"),
      ];
      elem.style.setProperty("isolation", "isolate");
    }
  }

  Object.assign(canvas.style, {
    borderRadius: "inherit",
    display: "block",
    height: "100%",
    inset: "0",
    maxHeight: "100%",
    maxWidth: "100%",
    pointerEvents: "none",
    position: "absolute",
    width: "100%",
    zIndex: "-1",
  });

  const revoke = () => {
    if (!url) return;
    domUrl.revokeObjectURL(url);
    if (renderState.url === url) renderState.url = null;
    url = null;
  };

  tempImage.onload = function () {
    if (renderState.generation !== generation) {
      revoke();
      return;
    }

    const staging = elem.ownerDocument.createElement("canvas");
    staging.height = canvasHeight;
    staging.width = canvasWidth;
    const stagingContext = staging.getContext("2d", { alpha: false });

    if (!stagingContext) {
      renderState.pending = false;
      renderState.signature = "";
      revoke();
      dispatch(elem, "metallicss:error", {
        error: new Error("Canvas 2D is not available"),
      });
      return;
    }

    stagingContext.drawImage(this, 0, 0, canvasWidth, canvasHeight);

    if (renderState.generation !== generation) {
      revoke();
      return;
    }

    canvas.height = canvasHeight;
    canvas.width = canvasWidth;
    context.drawImage(staging, 0, 0);
    renderState.pending = false;
    renderState.ready = true;
    renderState.image = null;
    elem.setAttribute("data-metallicss-ready", "");
    revoke();
    dispatch(elem, "metallicss:render", {
      duration: (view.performance?.now() ?? Date.now()) - startedAt,
      height: canvasHeight,
      width: canvasWidth,
    });
  };

  tempImage.onerror = () => {
    const isCurrent = renderState.generation === generation;
    revoke();

    if (!isCurrent) return;
    renderState.pending = false;
    renderState.ready = false;
    renderState.image = null;
    renderState.signature = "";
    dispatch(elem, "metallicss:error", {
      error: new Error("The metallic texture could not be rendered"),
    });
  };
  url = domUrl.createObjectURL(
    new view.Blob(
      [
        serializer.serializeToString(
          tag("svg", {
            inner: [
              tag("filter", {
                inner: [
                  createMap(elem.ownerDocument),
                  tag("feImage", {
                    props: {
                      ...dims,
                      ...sRGB,
                      href: `data:image/svg+xml;charset=utf-8,${encodeURIComponent(
                        serializer.serializeToString(
                          tag("svg", {
                            inner: [
                              tag("filter", {
                                inner: [
                                  tag("feGaussianBlur", {
                                    props: {
                                      ...sRGB,
                                      stdDeviation: absRawDepth * 3,
                                    },
                                  }),
                                ],
                                props: { id: "blur" },
                              }),
                              tag("rect", {
                                props: {
                                  fill: "rgb(1, 0, 1)",
                                  filter: "url(#blur)",
                                  height: `${lensHeight}%`,
                                  width: `${lensWidth}%`,
                                  rx,
                                  ry,
                                  x: `${(100 - lensWidth) / 2}%`,
                                  y: `${(100 - lensHeight) / 2}%`,
                                },
                              }),
                            ],
                            props: { ...dims, xmlns },
                          }),
                        ),
                      )}`,
                      preserveAspectRatio: "none",
                      result: "lens",
                    },
                  }),
                  tag("feBlend", {
                    props: { ...sRGB, in: "lens", in2: "map" },
                  }),
                  tag("feDisplacementMap", {
                    props: {
                      ...sRGB,
                      in: "SourceGraphic",
                      scale: -500,
                      xChannelSelector: "R",
                      yChannelSelector: "B",
                    },
                  }),
                ],
                props: { id: "warp", x: 0, y: 0 },
              }),
              tag("linearGradient", {
                inner: [
                  tag("stop", {
                    props: {
                      ["stop-color"]: fill,
                      ["stop-opacity"]: intensity / 2,
                      offset: 0.3,
                    },
                  }),
                  tag("stop", {
                    props: {
                      ["stop-color"]: fill,
                      ["stop-opacity"]: intensity / 8,
                      offset: 0.7,
                    },
                  }),
                  tag("stop", {
                    props: {
                      ["stop-color"]: fill,
                      ["stop-opacity"]: intensity / 2,
                      offset: 1,
                    },
                  }),
                ],
                props: {
                  ["color-interpolation"]: "sRGB",
                  gradientTransform: `rotate(${angle})`,
                  id: "color",
                },
              }),
              tag("g", {
                inner: inverse
                  ? [
                      ...inner,
                      tag("rect", {
                        props: {
                          ...dims,
                          fill: "#40404060",
                          style: "mix-blend-mode: multiply",
                        },
                      }),
                    ]
                  : inner,
                props: { filter: "url(#warp)" },
              }),
            ],
            props: {
              height: canvasHeight,
              width: canvasWidth,
              preserveAspectRatio: "none",
              style: `transform: scale(1, ${inverse ? "-" : ""}1)`,
              viewBox: "768 768 512 512",
              xmlns,
            },
          }),
        ),
      ],
      { type: "image/svg+xml;charset=utf-8" },
    ),
  );
  renderState.url = url;
  renderState.image = tempImage;
  tempImage.src = url;

  return canvas;
};

function restoreRenderer(element) {
  const state = renderStates.get(element);
  const view = element.ownerDocument?.defaultView;

  if (state) {
    state.generation += 1;
    state.pending = false;
    if (state.url && view?.URL) view.URL.revokeObjectURL(state.url);
    if (state.image) {
      state.image.onload = null;
      state.image.onerror = null;
    }

    for (const [property, [value, priority]] of Object.entries(state.originalStyles || {})) {
      const applied = property === "position" ? "relative" : "isolate";
      if (element.style.getPropertyValue(property) !== applied) continue;
      if (value) element.style.setProperty(property, value, priority);
      else element.style.removeProperty(property);
    }
  }

  directCanvas(element)?.remove();
  element.removeAttribute("data-metallicss-ready");
  renderStates.delete(element);
}

export function mount(element, options = {}) {
  if (!element || element.nodeType !== 1) {
    throw new TypeError("mount() expects an Element");
  }

  const existing = controllers.get(element);
  if (existing) return existing;

  const view = element.ownerDocument?.defaultView;
  if (!view) {
    throw new Error("mount() requires an Element connected to a Window");
  }

  const delay = number(options.debounce, 48, 0, 1000);
  let destroyed = false;
  let frame = 0;
  let timer = 0;
  const deferInitialRender =
    options.observe !== false && options.visibility !== false && Boolean(view.IntersectionObserver);
  let visible = !deferInitialRender;
  let forceNext = false;
  const observers = [];
  const requestFrame =
    view.requestAnimationFrame?.bind(view) || ((callback) => view.setTimeout(callback, 0));
  const cancelFrame =
    view.cancelAnimationFrame?.bind(view) || ((handle) => view.clearTimeout(handle));

  const cancelScheduled = () => {
    if (timer) view.clearTimeout(timer);
    if (frame) cancelFrame(frame);
    timer = 0;
    frame = 0;
  };

  const draw = () => {
    frame = 0;
    if (destroyed || !visible) return null;
    const force = forceNext;
    forceNext = false;
    return metallicss(element, { force });
  };

  const schedule = (force = false) => {
    if (destroyed) return;
    forceNext ||= force;
    if (timer) view.clearTimeout(timer);
    if (frame) cancelFrame(frame);

    const queueFrame = () => {
      timer = 0;
      frame = requestFrame(draw);
    };

    if (delay) timer = view.setTimeout(queueFrame, delay);
    else queueFrame();
  };

  const controller = {
    element,
    render(force = true) {
      cancelScheduled();
      forceNext = false;
      return metallicss(element, { force });
    },
    destroy() {
      if (destroyed) return;
      destroyed = true;
      cancelScheduled();
      observers.forEach((observer) => observer.disconnect());
      view.removeEventListener("resize", schedule);
      controllers.delete(element);
      restoreRenderer(element);
    },
  };

  controllers.set(element, controller);

  if (options.observe !== false) {
    if (view.MutationObserver) {
      const mutationObserver = new view.MutationObserver(() => schedule());
      mutationObserver.observe(element, {
        attributeFilter: ["class", "style"],
        attributes: true,
      });
      observers.push(mutationObserver);
    }

    if (view.ResizeObserver) {
      const resizeObserver = new view.ResizeObserver(() => schedule());
      resizeObserver.observe(element);
      observers.push(resizeObserver);
    } else {
      view.addEventListener("resize", schedule);
    }

    if (deferInitialRender) {
      const intersectionObserver = new view.IntersectionObserver((entries) => {
        visible = entries.some((entry) => entry.isIntersecting);
        if (visible) schedule(true);
      });
      intersectionObserver.observe(element);
      observers.push(intersectionObserver);
    }
  }

  if (visible) metallicss(element);

  return controller;
}

export function unmount(element) {
  if (!element || element.nodeType !== 1) return false;

  const controller = controllers.get(element);

  if (controller) {
    controller.destroy();
    return true;
  }

  if (renderStates.has(element) || directCanvas(element)) {
    restoreRenderer(element);
    return true;
  }

  return false;
}

function matchingElements(root) {
  if (!root?.querySelectorAll) return [];

  const matches = [];
  if (root.nodeType === 1 && root.matches?.(SELECTOR)) matches.push(root);
  matches.push(...root.querySelectorAll(SELECTOR));
  return matches;
}

export function refresh(root = globalThis.document) {
  const matches = root?.nodeType === 1 && controllers.has(root) ? [root] : matchingElements(root);

  matches.forEach((element) => {
    const controller = controllers.get(element);
    if (controller) controller.render(true);
    else metallicss(element, { force: true });
  });

  return matches.length;
}

export function observe(root = globalThis.document, options = {}) {
  if (!root?.querySelectorAll) return () => {};

  const view = root.defaultView || root.ownerDocument?.defaultView || globalThis.window;
  if (!view?.MutationObserver) return () => {};

  const owned = new Set();

  const add = (element) => {
    if (controllers.has(element)) return;
    owned.add(element);
    mount(element, options);
  };

  const remove = (element) => {
    if (!owned.delete(element)) return;
    unmount(element);
  };

  const scan = (node) => {
    if (node?.nodeType !== 1) return;
    if (node.matches?.(SELECTOR)) add(node);
    node.querySelectorAll?.(SELECTOR).forEach(add);
  };

  matchingElements(root).forEach(add);

  const mutationObserver = new view.MutationObserver((records) => {
    for (const record of records) {
      if (record.type === "attributes") {
        if (record.target.matches(SELECTOR)) add(record.target);
        else if (owned.has(record.target)) {
          owned.delete(record.target);
          unmount(record.target);
        }
        continue;
      }

      record.addedNodes.forEach(scan);
      record.removedNodes.forEach((removed) => {
        if (removed?.nodeType !== 1) return;
        remove(removed);
        removed.querySelectorAll?.("*").forEach(remove);
      });
    }
  });

  mutationObserver.observe(root, {
    attributeFilter: ["class"],
    attributes: true,
    childList: true,
    subtree: true,
  });

  return () => {
    mutationObserver.disconnect();
    owned.forEach(unmount);
    owned.clear();
  };
}

let disconnectAuto;

function startAuto() {
  if (!disconnectAuto) disconnectAuto = observe(document);
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", startAuto, { once: true });
  } else {
    startAuto();
  }
}

export default metallicss;
